import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, content-type, x-request-id",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};
const MENU_LOGO_DATA_URL = "data:image/png;base64,";

const responseJson = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });

function normalize(value: unknown) {
  return String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toLowerCase();
}
function slug(value: unknown) {
  return normalize(value).replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "evento";
}
function esc(value: unknown) {
  return String(value ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function brl(value: unknown) {
  const n = Number(value || 0);
  return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" })
    .format(Number.isFinite(n) ? n : 0);
}
function dateBr(value: unknown) {
  const m = String(value || "").slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? m[3] + "/" + m[2] + "/" + m[1] : "";
}
function dueDate(value: unknown) {
  const m = String(value || "").slice(0, 10).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return "";
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), 12));
  d.setUTCDate(d.getUTCDate() - 7);
  return new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC" }).format(d);
}
function endTime(start: string, duration: number | null) {
  if (!start || duration == null || !Number.isFinite(duration)) return "";
  const parts = start.split(":");
  const h = Number(parts[0]), m = Number(parts[1] || 0);
  if (!Number.isFinite(h) || !Number.isFinite(m)) return "";
  const total = h * 60 + m + Math.round(duration * 60);
  return String(Math.floor(total / 60) % 24).padStart(2, "0") + ":" + String(total % 60).padStart(2, "0");
}
function formatDoc(value: unknown) {
  const d = String(value ?? "").replace(/\D/g, "");
  if (d.length === 11) return d.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, "$1.$2.$3-$4");
  if (d.length === 14) return d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, "$1.$2.$3/$4-$5");
  return d;
}
function moneyWords(amount: number): string {
  if (!Number.isFinite(amount)) return "Zero reais";
  const units = ["", "um", "dois", "três", "quatro", "cinco", "seis", "sete", "oito", "nove"];
  const teens = ["dez", "onze", "doze", "treze", "quatorze", "quinze", "dezesseis", "dezessete", "dezoito", "dezenove"];
  const tens = ["", "dez", "vinte", "trinta", "quarenta", "cinquenta", "sessenta", "setenta", "oitenta", "noventa"];
  const hundreds = ["", "cento", "duzentos", "trezentos", "quatrocentos", "quinhentos", "seiscentos", "setecentos", "oitocentos", "novecentos"];
  const group = (n: number) => {
    if (!n) return "";
    if (n === 100) return "cem";
    const c = Math.floor(n / 100), d = Math.floor((n % 100) / 10), u = n % 10;
    const p: string[] = [];
    if (c) p.push(hundreds[c]);
    if (d === 1) p.push(teens[u]); else { if (d > 1) p.push(tens[d]); if (u) p.push(units[u]); }
    return p.join(" e ");
  };
  const integer = (n: number) => {
    if (!n) return "zero";
    const millions = Math.floor(n / 1000000);
    const thousands = Math.floor((n % 1000000) / 1000);
    const rest = n % 1000;
    const p: string[] = [];
    if (millions) p.push(millions === 1 ? "um milhão" : group(millions) + " milhões");
    if (thousands) p.push(thousands === 1 ? "mil" : group(thousands) + " mil");
    if (rest) p.push(group(rest));
    return p.join(rest < 100 && (millions || thousands) ? " e " : " ");
  };
  const rounded = Math.round(Math.abs(amount) * 100) / 100;
  const whole = Math.floor(rounded), cents = Math.round((rounded - whole) * 100);
  let out = whole ? integer(whole) + (whole === 1 ? " real" : " reais") : "";
  if (cents) out += (out ? " e " : "") + group(cents) + (cents === 1 ? " centavo" : " centavos");
  if (!out) out = "zero reais";
  return out.charAt(0).toUpperCase() + out.slice(1);
}
function parseNotes(raw: unknown): Record<string, any> {
  if (!raw) return {};
  if (typeof raw === "object" && !Array.isArray(raw)) return raw as Record<string, any>;
  if (typeof raw !== "string") return {};
  try {
    const p = JSON.parse(raw);
    return p && typeof p === "object" && !Array.isArray(p) ? p : {};
  } catch {
    const time = raw.match(/^Horário\s*:\s*(.+?)\s*$/imu)?.[1]?.trim();
    return time ? { event_time: time } : {};
  }
}
function selectedEntries(selected: any): Array<{ id?: string; name?: string }> {
  if (!selected) return [];
  if (Array.isArray(selected)) return selected.flatMap((v: any) => {
    if (typeof v === "string") return [{ id: v, name: v }];
    if (v && typeof v === "object") {
      const id = v.id || v.drink_id, name = v.name || v.nome;
      return id || name ? [{ id, name }] : [];
    }
    return [];
  });
  if (Array.isArray(selected.items)) return selected.items.map((v: any) => ({ id: v.drink_id || v.id, name: v.name || v.nome }));
  if (Array.isArray(selected.ids)) return selected.ids.map((id: string) => ({ id }));
  return [];
}
function resolveDrinks(selected: any, catalog: any[]) {
  const seen = new Set<string>();
  return selectedEntries(selected).flatMap((entry) => {
    const found = (entry.id ? catalog.find((d) => String(d.id) === String(entry.id)) : undefined) ||
      (entry.name ? catalog.find((d) => normalize(d.nome) === normalize(entry.name)) : undefined);
    const name = String(found?.nome || entry.name || entry.id || "").trim();
    if (!name) return [];
    const key = String(found?.id || normalize(name));
    if (seen.has(key)) return [];
    seen.add(key);
    return [{ id: key, name, description: String(found?.descricao || "").trim(), category: found?.categoria || undefined }];
  });
}
function weight(d: any) {
  const nl = Math.max(1, Math.ceil(String(d.name || "").length / 30));
  const desc = String(d.description || "");
  const dl = desc ? Math.max(1, Math.ceil(desc.length / 58)) : 0;
  return 1.15 + (nl - 1) * 0.35 + dl * 0.72;
}
function paginate(drinks: any[], max = 18.5) {
  if (!drinks.length) return [[]];
  const pages: any[][] = []; let current: any[] = []; let total = 0;
  for (const d of drinks) {
    const w = weight(d);
    if (current.length && total + w > max) { pages.push(current); current = []; total = 0; }
    current.push(d); total += w;
  }
  if (current.length) pages.push(current);
  return pages;
}
function personalization(event: any, custom?: string | null) {
  const type = normalize(event.event_type);
  const eventName = String(custom || event.event_name || event.client_name || "").trim();
  if (type.includes("casamento")) {
    const names = [event.groom_name, event.bride_name].filter(Boolean);
    const fallback = eventName.split(/\s*(?:&| e )\s*/i).filter(Boolean);
    const r = names.length ? names : fallback;
    return {
      kind: "wedding",
      initials: r.slice(0, 2).map((n: string) => String(n).trim().charAt(0).toUpperCase()).join(""),
      label: r.length >= 2 ? r.slice(0, 2).join(" & ") : eventName,
      date: event.date ? dateBr(event.date).replace(/\//g, ".") : undefined,
    };
  }
  if (type.includes("anivers")) return { kind: "birthday", label: custom || "Happy Birthday" };
  if (type.includes("corporat") || type.includes("confratern")) return { kind: "corporate", label: eventName || "Cheers!" };
  if (type.includes("despedida") || type.includes("solteir")) return { kind: "bachelor", label: custom || "Game Over" };
  return { kind: "generic", label: eventName };
}
async function callJson(url: string, key: string, fn: string, body: any, requestId: string) {
  const r = await fetch(url + "/functions/v1/" + fn, {
    method: "POST",
    headers: { Authorization: "Bearer " + key, apikey: key, "Content-Type": "application/json", "x-request-id": requestId },
    body: JSON.stringify(body),
  });
  const raw = await r.text();
  let p: any = {};
  try { p = raw ? JSON.parse(raw) : {}; } catch { p = { error: raw.slice(0, 500) }; }
  if (!r.ok || p?.success === false || p?.ok === false) {
    const e: any = new Error(p?.error || p?.message || ("Falha em " + fn + " (HTTP " + r.status + ")."));
    e.status = r.status; e.payload = p; throw e;
  }
  return p;
}
async function callPdf(url: string, key: string, fn: string, body: any, requestId: string) {
  const r = await fetch(url + "/functions/v1/" + fn, {
    method: "POST",
    headers: { Authorization: "Bearer " + key, apikey: key, "Content-Type": "application/json", "x-request-id": requestId },
    body: JSON.stringify(body),
  });
  if (!r.ok) {
    const raw = await r.text(); let message = raw.slice(0, 500);
    try { const p = JSON.parse(raw); message = p.error || p.message || message; } catch {}
    const e: any = new Error(message || ("Falha em " + fn)); e.status = r.status; throw e;
  }
  const bytes = new Uint8Array(await r.arrayBuffer());
  if (bytes.length < 5 || new TextDecoder().decode(bytes.slice(0, 5)) !== "%PDF-") throw new Error("O gerador não retornou um PDF válido.");
  return bytes;
}
async function digest(bytes: Uint8Array) {
  const d = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(d)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
function b64(bytes: Uint8Array) {
  let s = ""; const size = 0x8000;
  for (let i = 0; i < bytes.length; i += size) s += String.fromCharCode(...bytes.subarray(i, Math.min(i + size, bytes.length)));
  return btoa(s);
}
function renderContract(template: any, vars: Record<string, string>) {
  const schema = template?.variables_schema;
  let body = schema && typeof schema === "object" && !Array.isArray(schema) && typeof schema.content === "string"
    ? schema.content : String(template?.description || "");
  body = body.replace(/(\{\{\s*[\w.]+\s*\}\})(?:x{1,4})/gi, "$1").replace(/(\[\s*[\w._]+\s*\])(?:x{1,4})/gi, "$1");
  for (const [key, value] of Object.entries(vars)) {
    if (!value) continue;
    const safeKey = key.replace(/\./g, "\\.");
    body = body
      .replace(new RegExp("\\{\\{\\s*" + safeKey + "\\s*\\}\\}(?:xx|x)?", "gi"), esc(value))
      .replace(new RegExp("\\[\\s*" + safeKey.toUpperCase() + "\\s*\\](?:xx|x)?", "gi"), esc(value));
  }
  const unresolved = Array.from(new Set(Array.from(body.matchAll(/\{\{\s*([a-zA-Z0-9._]+)\s*\}\}|\[([A-Z0-9_]+)\]/g)).map((m) => m[1] || m[2])));
  return { html: body, unresolved };
}
function randomShareToken() {
  const bytes = new Uint8Array(32);
  crypto.getRandomValues(bytes);
  return btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
}

async function createDocumentShareLink(
  admin: any,
  supabaseUrl: string,
  input: {
    eventId: string;
    documentKind: "menu" | "contract" | "proposal";
    bucket: string;
    path: string;
    filename: string;
    createdBy?: string | null;
    expiresInSeconds: number;
  },
) {
  const token = randomShareToken();
  const tokenHash = await digest(new TextEncoder().encode(token));
  const expiresAt = new Date(Date.now() + input.expiresInSeconds * 1000).toISOString();

  const { error } = await admin.from("document_share_links").insert({
    token_hash: tokenHash,
    event_id: input.eventId,
    document_kind: input.documentKind,
    bucket_id: input.bucket,
    object_path: input.path,
    filename: input.filename,
    mime_type: "application/pdf",
    expires_at: expiresAt,
    created_by: input.createdBy || null,
  });
  if (error) throw error;

  return {
    url: supabaseUrl + "/functions/v1/goat-ai-document-share?token=" + encodeURIComponent(token),
    expiresAt,
  };
}
async function proposal(admin: any, url: string, key: string, userId: string, eventId: string, requestId: string) {
  const { data: budget, error } = await admin.from("event_budget_versions").select("id").eq("event_id", eventId).eq("is_current", true).maybeSingle();
  if (error) throw error;
  if (!budget?.id) { const e: any = new Error("O evento ainda não possui orçamento atual para gerar a proposta."); e.status = 422; throw e; }
  const p = await callJson(url, key, "canva-generate-proposal", {
    event_id: eventId, budget_version_id: budget.id, requested_by_user_id: userId, internal_source: "gia",
  }, requestId);
  return { success: true, action: "generate_proposal", pdf_url: p.pdf_url, filename: p.filename, proposal_id: p.proposal?.id || null,
    message: "Proposta comercial gerada com sucesso.\n\nPDF: " + p.pdf_url };
}
async function menu(admin: any, url: string, key: string, userId: string, event: any, requestId: string) {
  const results = await Promise.all([
    admin.from("event_budget_versions").select("selected_drinks").eq("event_id", event.id).eq("is_current", true).maybeSingle(),
    admin.from("drinks").select("id,nome,descricao,categoria"),
    admin.from("event_menu_settings").select("*").eq("event_id", event.id).maybeSingle(),
  ]);
  if (results[0].error) throw results[0].error;
  if (results[1].error) throw results[1].error;
  const drinks = resolveDrinks(results[0].data?.selected_drinks || event.drinks || [], results[1].data || []);
  if (!drinks.length) { const e: any = new Error("O orçamento atual não possui drinks válidos para gerar o cardápio."); e.status = 422; throw e; }
  const pages = paginate(drinks); const tw = drinks.reduce((s, d) => s + weight(d), 0);
  const layout = drinks.length <= 5 && tw <= 10 ? "expanded" : (drinks.length <= 8 && pages.length === 1 && tw <= 15 ? "standard" : "compact");
  const settings = results[2].data;
  const model = { title: "Menu", subtitle: event.event_name || undefined, drinks, layout, columns: 1, pages,
    personalization: personalization(event, settings?.custom_label), artworkMode: settings?.artwork_mode || "automatic",
    artworkUrl: settings?.artwork_url || null, warnings: [] };
  const pdf = await callPdf(url, key, "event-menu-render-pdf", { menu: model, logoDataUrl: MENU_LOGO_DATA_URL, internal_source: "gia" }, requestId);
  const filename = "cardapio-" + slug(event.event_name || event.client_name) + ".pdf";
  const path = "events/" + event.id + "/menus/" + Date.now() + "-" + filename;
  const up = await admin.storage.from("generated-event-menus").upload(path, pdf, { contentType: "application/pdf", upsert: false, cacheControl: "3600" });
  if (up.error) throw up.error;
  const share = await createDocumentShareLink(admin, url, {
    eventId: event.id,
    documentKind: "menu",
    bucket: "generated-event-menus",
    path,
    filename,
    createdBy: userId,
    expiresInSeconds: 60 * 60 * 24 * 7,
  });
  return {
    success: true,
    action: "generate_menu",
    pdf_url: share.url,
    filename,
    storage_path: path,
    expires_at: share.expiresAt,
    expires_in: "7 dias",
    message: "Cardápio gerado com sucesso.\n\nPDF: " + share.url,
  };
}
async function contractRecords(admin: any, event: any) {
  const cr = await admin.from("event_contracts").select("*").eq("event_id", event.id).neq("status", "cancelled").order("created_at", { ascending: false });
  if (cr.error) throw cr.error;
  if ((cr.data || []).length > 1) { const e: any = new Error("Há mais de um contrato ativo neste evento. Regularize a duplicidade antes de enviar para assinatura."); e.status = 409; throw e; }
  let contract = cr.data?.[0] || null;
  let template: any = null, signer: any = null;
  if (contract?.template_id) template = (await admin.from("contract_templates").select("*").eq("id", contract.template_id).maybeSingle()).data;
  if (!template) {
    const q = await admin.from("contract_templates").select("*").eq("is_default", true).eq("status", "active").order("created_at", { ascending: false }).limit(1).maybeSingle();
    if (q.error) throw q.error; template = q.data;
  }
  if (!template) { const e: any = new Error("Nenhum template oficial ativo de contrato está configurado."); e.status = 422; throw e; }
  if (contract?.signer_id) signer = (await admin.from("contract_signers").select("*").eq("id", contract.signer_id).eq("is_active", true).maybeSingle()).data;
  if (!signer) {
    const q = await admin.from("contract_signers").select("*").eq("is_active", true).order("name", { ascending: true }).limit(1).maybeSingle();
    if (q.error) throw q.error; signer = q.data;
  }
  if (!signer) { const e: any = new Error("Nenhum responsável legal ativo da Goat Bar está configurado."); e.status = 422; throw e; }
  const bq = await admin.from("event_budget_versions").select("*").eq("event_id", event.id).eq("is_current", true).maybeSingle();
  if (bq.error) throw bq.error;
  if (!bq.data) { const e: any = new Error("O evento não possui orçamento atual para compilar o contrato."); e.status = 422; throw e; }
  if (!contract) {
    const ins = await admin.from("event_contracts").insert({ event_id: event.id, template_id: template.id, signer_id: signer.id,
      budget_version_id: bq.data.id, status: "draft", version: 1, generated_at: new Date().toISOString() }).select().single();
    if (ins.error || !ins.data) throw ins.error || new Error("Falha ao criar registro do contrato."); contract = ins.data;
  } else if (!contract.template_id || !contract.signer_id || !contract.budget_version_id) {
    const upd = await admin.from("event_contracts").update({ template_id: contract.template_id || template.id, signer_id: contract.signer_id || signer.id,
      budget_version_id: contract.budget_version_id || bq.data.id, updated_at: new Date().toISOString() }).eq("id", contract.id).select().single();
    if (upd.error || !upd.data) throw upd.error || new Error("Falha ao completar dados do contrato."); contract = upd.data;
  }
  return { contract, template, signer, budget: bq.data };
}
async function contractVars(admin: any, event: any, budget: any, signer: any) {
  const q = await Promise.all([
    admin.from("event_contract_client_data").select("*").eq("event_id", event.id).maybeSingle(),
    admin.from("drinks").select("id,nome"),
  ]);
  const client = q[0].data, notes = parseNotes(client?.notes);
  const start = String(notes.event_time || notes.horario || notes.eventTime || event.event_time || "").trim();
  const duration = event.duration_hours == null ? null : Number(event.duration_hours);
  const total = Number(budget.final_budget_value ?? event.current_budget_value ?? 0);
  const guests = Number(event.guests || budget.guest_count || 0);
  const perPerson = Number(budget.average_value_per_person || (total > 0 && guests > 0 ? total / guests : 0));
  const names = resolveDrinks(budget.selected_drinks || event.drinks || [], q[1].data || []).map((d) => d.name);
  const vars: Record<string, string> = {
    "cliente.nome": String(client?.client_name || event.client_name || "").trim(),
    "cliente.documento": formatDoc(client?.cpf_cnpj || notes.cpf_cnpj || ""),
    "cliente.email": String(client?.email || event.email || "").trim(),
    "evento.data": dateBr(event.date),
    "evento.hora_inicio": start,
    "evento.hora_fim": endTime(start, duration),
    "evento.endereco_local": String(notes.venue_address || client?.address || event.event_location || "").trim(),
    "evento.convidados": guests > 0 ? String(guests) : "",
    "evento.valor_por_pessoa": perPerson > 0 ? brl(perPerson) : "",
    "evento.valor_por_pessoa_extenso": perPerson > 0 ? moneyWords(perPerson) : "",
    "financeiro.valor_total": total > 0 ? brl(total) : "",
    "financeiro.valor_total_extenso": total > 0 ? moneyWords(total) : "",
    "financeiro.data_pagamento_final": dueDate(event.date),
    "empresa.responsavel": String(signer.name || "").trim(),
    "empresa.cpf_responsavel": formatDoc(signer.cpf),
    "empresa.endereco_responsavel": String(signer.address || "").trim(),
    "cardapio.drinks": names.join(", "),
    "geral.data_emissao": new Intl.DateTimeFormat("pt-BR", { timeZone: "America/Sao_Paulo" }).format(new Date()),
  };
  const required = ["cliente.nome","cliente.documento","evento.data","evento.hora_inicio","evento.hora_fim","evento.endereco_local",
    "evento.convidados","evento.valor_por_pessoa","evento.valor_por_pessoa_extenso","financeiro.valor_total","financeiro.valor_total_extenso",
    "financeiro.data_pagamento_final","empresa.responsavel","empresa.cpf_responsavel","empresa.endereco_responsavel","cardapio.drinks"];
  const missing = required.filter((k) => !vars[k]);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(vars["cliente.email"])) missing.push("cliente.email");
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(signer.email || ""))) missing.push("empresa.email_responsavel");
  return { vars, missing };
}
async function contractAndSend(admin: any, url: string, key: string, userId: string, event: any, requestId: string) {
  const r = await contractRecords(admin, event), contract = r.contract;
  const active = await admin.from("contract_signature_requests").select("id,dispatch_status").eq("contract_id", contract.id)
    .eq("signature_provider", "assinafy").eq("document_kind", "contract").neq("dispatch_status", "obsolete")
    .order("created_at", { ascending: false }).limit(1).maybeSingle();
  if (active.data && ["pending_signature","signed","completed"].includes(active.data.dispatch_status)) {
    let link = contract.signed_file_url || null;
    if (!link && contract.generated_file_path) {
      try {
        link = (await createDocumentShareLink(admin, url, {
          eventId: event.id,
          documentKind: "contract",
          bucket: "contract-documents",
          path: contract.generated_file_path,
          filename: "contrato-" + slug(event.event_name || event.client_name) + ".pdf",
          createdBy: userId,
          expiresInSeconds: 60 * 60 * 24,
        })).url;
      } catch {}
    }
    if (!link) link = contract.generated_file_url || null;
    return { success: true, action: "generate_contract_and_send", reused: true, contract_id: contract.id,
      signature_request_id: active.data.id, signature_status: active.data.dispatch_status, pdf_url: link,
      message: "O contrato já havia sido enviado para assinatura; o envio existente foi reutilizado." + (link ? "\n\nPDF: " + link : "") };
  }
  const cv = await contractVars(admin, event, r.budget, r.signer);
  if (cv.missing.length) { const e: any = new Error("Não foi possível gerar o contrato. Campos obrigatórios pendentes: " + cv.missing.join(", ") + "."); e.status = 422; e.missing_fields = cv.missing; throw e; }
  const rendered = renderContract(r.template, cv.vars);
  if (rendered.unresolved.length) { const e: any = new Error("O template ainda possui campos não resolvidos: " + rendered.unresolved.join(", ") + "."); e.status = 422; e.missing_fields = rendered.unresolved; throw e; }
  const title = "Contrato Goat Bar - " + String(event.event_name || event.client_name || "Evento").trim();
  const pdf = await callPdf(url, key, "contract-render-pdf", { html: rendered.html, title, contractId: contract.id,
    requested_by_user_id: userId, internal_source: "gia" }, requestId);
  const hash = await digest(pdf), filename = "contrato-" + slug(event.event_name || event.client_name) + ".pdf";
  const path = "events/" + event.id + "/contracts/" + contract.id + "/" + hash.slice(0, 16) + "-" + filename;
  const up = await admin.storage.from("contract-documents").upload(path, pdf, { contentType: "application/pdf", upsert: true, cacheControl: "3600" });
  if (up.error) throw up.error;
  const contractShare = await createDocumentShareLink(admin, url, {
    eventId: event.id,
    documentKind: "contract",
    bucket: "contract-documents",
    path,
    filename,
    createdBy: userId,
    expiresInSeconds: 60 * 60 * 24,
  });
  const link = contractShare.url;
  const snapshot = contract.legal_snapshot || {
    captured_at: new Date().toISOString(),
    cliente: { nome: cv.vars["cliente.nome"], documento: cv.vars["cliente.documento"], email: cv.vars["cliente.email"] },
    empresa: { responsavel: cv.vars["empresa.responsavel"], cpf_responsavel: cv.vars["empresa.cpf_responsavel"], endereco_responsavel: cv.vars["empresa.endereco_responsavel"] },
    evento: { data: cv.vars["evento.data"], convidados: cv.vars["evento.convidados"], valor_por_pessoa: cv.vars["evento.valor_por_pessoa"], valor_por_pessoa_extenso: cv.vars["evento.valor_por_pessoa_extenso"] },
    financeiro: { valor_total: cv.vars["financeiro.valor_total"], data_vencimento: cv.vars["financeiro.data_pagamento_final"] },
    cardapio: { drinks: cv.vars["cardapio.drinks"] },
  };
  const save = await admin.from("event_contracts").update({ legal_snapshot: snapshot, generated_file_path: path, generated_file_url: link,
    generated_at: new Date().toISOString(), updated_at: new Date().toISOString() }).eq("id", contract.id);
  if (save.error) throw save.error;
  const dispatch = await callJson(url, key, "assinafy-create-doc", { contractId: contract.id, documentKind: "contract", pdfBase64: b64(pdf),
    pdfHash: hash, documentTitle: title, requested_by_user_id: userId, internal_source: "gia" }, requestId);
  return { success: true, action: "generate_contract_and_send", contract_id: contract.id, pdf_url: link, filename,
    signature_request_id: dispatch.signatureRequestId || null, signature_status: dispatch.status || "pending_signature",
    dispatch_outcome: dispatch.dispatchOutcome || null, external_document_id: dispatch.externalDocumentId || null,
    message: (dispatch.message || "Contrato enviado para assinatura com sucesso.") + "\n\nPDF: " + link };
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  if (req.method !== "POST") return responseJson({ success: false, error: "Método não permitido." }, 405);
  const requestId = req.headers.get("x-request-id") || crypto.randomUUID();
  try {
    const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "";
    const url = (Deno.env.get("SUPABASE_URL") || "").replace(/\/$/, "");
    if (!key || req.headers.get("Authorization") !== "Bearer " + key) return responseJson({ success: false, error: "Acesso interno não autorizado." }, 401);
    const body = await req.json(), action = String(body?.action || ""), eventId = String(body?.event_id || "").trim();
    const userId = String(body?.requested_by_user_id || "").trim();
    if (!eventId || !userId) return responseJson({ success: false, error: "event_id e requested_by_user_id são obrigatórios." }, 422);
    const admin = createClient(url, key, { auth: { persistSession: false } });
    const user = await admin.auth.admin.getUserById(userId);
    if (user.error || !user.data?.user) return responseJson({ success: false, error: "Usuário solicitante não encontrado." }, 403);
    const ev = await admin.from("events").select("*").eq("id", eventId).single();
    if (ev.error || !ev.data) return responseJson({ success: false, error: "Evento não encontrado." }, 404);
    console.info("[goat-ai-document-actions]", { requestId, action, eventId, userId, channel: body?.channel || null });
    if (action === "generate_proposal") return responseJson(await proposal(admin, url, key, userId, eventId, requestId));
    if (action === "generate_menu") return responseJson(await menu(admin, url, key, userId, ev.data, requestId));
    if (action === "generate_contract_and_send") return responseJson(await contractAndSend(admin, url, key, userId, ev.data, requestId));
    return responseJson({ success: false, error: "Ação de documento desconhecida." }, 400);
  } catch (error: any) {
    console.error("[goat-ai-document-actions][error]", { requestId, message: error?.message || String(error), status: error?.status || 500 });
    return responseJson({ success: false, error: error?.message || "Falha interna no processamento do documento.",
      missing_fields: error?.missing_fields || undefined }, Number(error?.status) || 500);
  }
});
